package com.example.home_api.web;

import jakarta.servlet.http.HttpSession;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Controller;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.ui.Model;
import org.springframework.util.LinkedMultiValueMap;
import org.springframework.util.MultiValueMap;
import org.springframework.web.bind.annotation.*;

import java.sql.Timestamp;
import java.time.*;
import java.util.*;

@Controller
public class PurchaseDataController {
    private final JdbcTemplate jdbc;
    public PurchaseDataController(JdbcTemplate jdbc){this.jdbc=jdbc;}

    @GetMapping("/shopping") String input(HttpSession s,Authentication auth,Model m){String g=group(s);masters(g,m);m.addAttribute("patterns",patterns(g,"INPUT"));m.addAttribute("today",LocalDate.now());m.addAttribute("currentUserId",auth.getName());m.addAttribute("recentPurchases",jdbc.queryForList("SELECT s.id,s.shopping_date,s.type,s.amount,s.settlement,s.fixed_flag,s.create_date,c.category_name,pm.payment_name,u.user_name FROM shopping s LEFT JOIN category c ON c.id=s.category_id LEFT JOIN payment_method pm ON pm.id=s.payment_method_id LEFT JOIN \"user\" u ON u.user_id=s.shopping_user_id WHERE s.group_id=? ORDER BY s.create_date DESC,s.id DESC LIMIT 10",g));return "shopping";}
    @PostMapping("/shopping") @Transactional String create(@RequestParam MultiValueMap<String,String> p,HttpSession s,Authentication a){String g=group(s);if(isClosed(g,date(p,"shoppingDate")))return "redirect:/shopping?error=closed";insert(g,a.getName(),p);return "redirect:/shopping?created";}

    @GetMapping("/shopping/templates") String templates(HttpSession s,Model m){String g=group(s);m.addAttribute("templates",jdbc.queryForList("SELECT p.*,(SELECT string_agg(c.category_name,'、' ORDER BY c.category_no) FROM category c WHERE c.id=ANY(string_to_array(COALESCE(p.category_ids,''),','))) category_names,(SELECT string_agg(pm.payment_name,'、' ORDER BY pm.payment_no) FROM payment_method pm WHERE pm.id=ANY(string_to_array(COALESCE(p.payment_method_ids,''),','))) payment_names,(SELECT string_agg(u.user_name,'、' ORDER BY gm.member_no,u.user_name) FROM group_member gm JOIN \"user\" u ON u.user_id=gm.user_id WHERE gm.group_id=p.group_id AND u.user_id=ANY(string_to_array(COALESCE(p.member_ids,''),','))) member_names,(SELECT string_agg(sl.label_name,'、' ORDER BY sl.label_no) FROM shopping_label sl WHERE sl.id=ANY(string_to_array(COALESCE(p.label_ids,''),','))) label_names FROM purchase_pattern p WHERE p.group_id=? AND p.pattern_type='TEMPLATE' AND p.disabled_flag=0 ORDER BY p.display_no",g));m.addAttribute("today",LocalDate.now());return "purchase-template-entry";}
    @PostMapping("/shopping/templates") @Transactional String templatesCreate(@RequestParam(required=false) List<String> templateIds,@RequestParam String shoppingDate,HttpSession s,Authentication a){String g=group(s);if(templateIds==null||templateIds.isEmpty())return "redirect:/shopping/templates?error=unselected";LocalDate d=parseDate(shoppingDate);if(isClosed(g,d))return "redirect:/shopping/templates?error=closed";List<Map<String,Object>> selected=new ArrayList<>();for(String id:templateIds.stream().distinct().toList()){var rows=jdbc.queryForList("SELECT * FROM purchase_pattern WHERE id=? AND group_id=? AND pattern_type='TEMPLATE' AND disabled_flag=0",id,g);if(rows.isEmpty())return "redirect:/shopping/templates?error=missing";Map<String,Object>x=rows.get(0);if(x.get("amount")==null||first(x.get("category_ids"),null)==null||first(x.get("payment_method_ids"),null)==null)return "redirect:/shopping/templates?error=incomplete";selected.add(x);}for(Map<String,Object>x:selected)insertTemplate(g,a.getName(),d,x);return "redirect:/shopping/templates?created="+selected.size();}
    @PostMapping("/shopping/templates/{id}") @Transactional String template(@PathVariable String id,@RequestParam String shoppingDate,HttpSession s,Authentication a){String g=group(s);var rows=jdbc.queryForList("SELECT * FROM purchase_pattern WHERE id=? AND group_id=? AND pattern_type='TEMPLATE' AND disabled_flag=0",id,g);if(rows.isEmpty())return "redirect:/shopping/templates?error=missing";LocalDate d=parseDate(shoppingDate);if(isClosed(g,d))return "redirect:/shopping/templates?error=closed";Map<String,Object>x=rows.get(0);if(x.get("amount")==null||first(x.get("category_ids"),null)==null||first(x.get("payment_method_ids"),null)==null)return "redirect:/shopping/templates?error=incomplete";jdbc.update("INSERT INTO shopping(group_id,shopping_date,shopping_user_id,category_id,type,payment,settlement,amount,shopping_label_id,remarks,create_user_id,fixed_flag,create_date,update_date,payment_method_id,shopping_label_ids) VALUES (?,?,?,?,?,?,?,?,?,?,?,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?,?)",g,Timestamp.valueOf(d.atStartOfDay()),first(x.get("member_ids"),a.getName()),first(x.get("category_ids"),null),type(x.get("transaction_type")),0,settlement(x.get("settlement_status")),number(x.get("amount")),null,text(x.get("note")),a.getName(),first(x.get("payment_method_ids"),null),text(x.get("label_ids")));return "redirect:/shopping/templates?created";}

    @GetMapping("/group/purchases") String manage(@RequestParam MultiValueMap<String,String> p,HttpSession s,Model m){String g=group(s);MultiValueMap<String,String> filters=new LinkedMultiValueMap<>();filters.addAll(p);if(p.isEmpty()){YearMonth current=YearMonth.now();filters.set("dateFrom",current.atDay(1).toString());filters.set("dateTo",current.atEndOfMonth().toString());}masters(g,m);m.addAttribute("patterns",patterns(g,"SEARCH"));m.addAttribute("filters",filters);List<Map<String,Object>> rows=search(g,filters);rows.forEach(r->r.put("reference_warning",invalidShopping(g,((Number)r.get("id")).longValue())?1:0));m.addAttribute("rows",rows);m.addAttribute("summary",purchaseSummary(rows));m.addAttribute("invalidReferenceCount",rows.stream().filter(r->numberValue(r.get("reference_warning"))==1&&numberValue(r.get("fixed_flag"))!=1).count());return "group/purchase-manage";}
    @PostMapping("/group/purchases/settle") @Transactional String settle(@RequestParam(required=false) List<Long> ids,HttpSession s){String g=group(s);if(ids!=null)for(Long id:ids)jdbc.update("UPDATE shopping SET settlement=2,update_date=CURRENT_TIMESTAMP WHERE id=? AND group_id=? AND fixed_flag=0",id,g);return "redirect:/group/purchases?settled";}
    @PostMapping("/group/purchases/delete") @Transactional String bulkDelete(@RequestParam(required=false) List<Long> ids,HttpSession s){String g=group(s);if(ids!=null)for(Long id:ids)jdbc.update("DELETE FROM shopping s WHERE s.id=? AND s.group_id=? AND COALESCE(s.settlement,1)<>2 AND s.fixed_flag=0 AND NOT EXISTS(SELECT 1 FROM fixed f WHERE f.group_id=s.group_id AND f.year=EXTRACT(YEAR FROM s.shopping_date)::int AND f.month=EXTRACT(MONTH FROM s.shopping_date)::int)",id,g);return "redirect:/group/purchases?deleted";}
    @GetMapping("/group/purchases/{id}") String edit(@PathVariable long id,HttpSession s,Model m){String g=group(s);var rows=jdbc.queryForList("SELECT s.*,CASE WHEN s.fixed_flag=1 OR EXISTS(SELECT 1 FROM fixed f WHERE f.group_id=s.group_id AND f.year=EXTRACT(YEAR FROM s.shopping_date)::int AND f.month=EXTRACT(MONTH FROM s.shopping_date)::int) THEN 1 ELSE 0 END monthly_closed,"+invalidReferenceCase("s")+" reference_warning FROM shopping s WHERE s.id=? AND s.group_id=?",id,g);if(rows.isEmpty())return "redirect:/group/purchases";masters(g,m);m.addAttribute("row",rows.get(0));return "group/purchase-edit";}
    @PostMapping("/group/purchases/{id}") @Transactional String update(@PathVariable long id,@RequestParam MultiValueMap<String,String> p,HttpSession s){String g=group(s);if(closedRow(g,id))return "redirect:/group/purchases/"+id+"?error=closed";LocalDate d=date(p,"shoppingDate");if(isClosed(g,d))return "redirect:/group/purchases/"+id+"?error=closed";jdbc.update("UPDATE shopping SET shopping_date=?,category_id=?,type=?,payment_method_id=?,amount=?,shopping_user_id=?,settlement=?,shopping_label_ids=?,remarks=?,update_date=CURRENT_TIMESTAMP WHERE id=? AND group_id=? AND fixed_flag=0",Timestamp.valueOf(d.atStartOfDay()),value(p,"categoryId"),type(value(p,"type")),value(p,"paymentMethodId"),positive(value(p,"amount")),value(p,"memberId"),settlement(value(p,"settlement")),csv(p,"labelIds"),value(p,"remarks"),id,g);return "redirect:/group/purchases/"+id+"?updated";}
    @PostMapping("/group/purchases/{id}/delete") @Transactional String delete(@PathVariable long id,HttpSession s){String g=group(s);int deleted=jdbc.update("DELETE FROM shopping s WHERE s.id=? AND s.group_id=? AND COALESCE(s.settlement,1)<>2 AND s.fixed_flag=0 AND NOT EXISTS(SELECT 1 FROM fixed f WHERE f.group_id=s.group_id AND f.year=EXTRACT(YEAR FROM s.shopping_date)::int AND f.month=EXTRACT(MONTH FROM s.shopping_date)::int)",id,g);return deleted>0?"redirect:/group/purchases?deleted":"redirect:/group/purchases/"+id+"?error=notDeletable";}

    @GetMapping("/group/monthly") String monthly(@RequestParam(required=false) Integer year,HttpSession s,Model m){String g=group(s);int y=year==null?LocalDate.now().getYear():year;m.addAttribute("year",y);m.addAttribute("months",monthStatus(g,y));return "group/monthly";}
    @GetMapping("/group/monthly/{year}/{month}") String monthlyDetail(@PathVariable int year,@PathVariable int month,HttpSession s,Model m){String g=group(s);YearMonth ym=YearMonth.of(year,month);m.addAttribute("year",year);m.addAttribute("month",month);m.addAttribute("closed",closed(g,year,month));m.addAttribute("dateReady",!LocalDate.now().isBefore(ym.atEndOfMonth()));m.addAttribute("unsettled",count(g,"SELECT count(*) FROM shopping WHERE group_id=? AND EXTRACT(YEAR FROM shopping_date)=? AND EXTRACT(MONTH FROM shopping_date)=? AND COALESCE(settlement,1)<>2",year,month));m.addAttribute("budgetReady",budgetReady(g,year,month));m.addAttribute("invalidReferences",invalidReferences(g,year,month));m.addAttribute("members",monthlyMembers(g,year,month));return "group/monthly-detail";}
    @PostMapping("/group/monthly/{year}/{month}/close") @Transactional String close(@PathVariable int year,@PathVariable int month,HttpSession s){String g=group(s);YearMonth ym=YearMonth.of(year,month);if(LocalDate.now().isBefore(ym.atEndOfMonth())||count(g,"SELECT count(*) FROM shopping WHERE group_id=? AND EXTRACT(YEAR FROM shopping_date)=? AND EXTRACT(MONTH FROM shopping_date)=? AND COALESCE(settlement,1)<>2",year,month)>0||!budgetReady(g,year,month)||invalidReferences(g,year,month)>0)return "redirect:/group/monthly/"+year+"/"+month+"?error=condition";jdbc.update("INSERT INTO fixed(group_id,year,month,remarks,create_date,update_date) VALUES (?,?,?,'月次確定',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON CONFLICT(group_id,year,month) DO UPDATE SET update_date=CURRENT_TIMESTAMP",g,year,month);jdbc.update("UPDATE shopping SET fixed_flag=1,update_date=CURRENT_TIMESTAMP WHERE group_id=? AND EXTRACT(YEAR FROM shopping_date)=? AND EXTRACT(MONTH FROM shopping_date)=?",g,year,month);jdbc.update("UPDATE budgets SET fixed_flag=1,update_date=CURRENT_TIMESTAMP WHERE group_id=? AND year=? AND month=?",g,year,month);return "redirect:/group/monthly/"+year+"/"+month+"?closed";}
    @PostMapping("/group/monthly/{year}/{month}/reopen") @Transactional String reopen(@PathVariable int year,@PathVariable int month,HttpSession s){String g=group(s);jdbc.update("DELETE FROM fixed WHERE group_id=? AND year=? AND month=?",g,year,month);jdbc.update("UPDATE shopping SET fixed_flag=0,update_date=CURRENT_TIMESTAMP WHERE group_id=? AND EXTRACT(YEAR FROM shopping_date)=? AND EXTRACT(MONTH FROM shopping_date)=?",g,year,month);jdbc.update("UPDATE budgets SET fixed_flag=0,update_date=CURRENT_TIMESTAMP WHERE group_id=? AND year=? AND month=?",g,year,month);return "redirect:/group/monthly/"+year+"/"+month+"?reopened";}

    private void insert(String g,String user,MultiValueMap<String,String>p){jdbc.update("INSERT INTO shopping(group_id,shopping_date,shopping_user_id,category_id,type,payment,settlement,amount,shopping_label_id,remarks,create_user_id,fixed_flag,create_date,update_date,payment_method_id,shopping_label_ids) VALUES (?,?,?,?,?,0,?,?,NULL,?,?,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?,?)",g,Timestamp.valueOf(date(p,"shoppingDate").atStartOfDay()),value(p,"memberId"),value(p,"categoryId"),type(value(p,"type")),settlement(value(p,"settlement")),positive(value(p,"amount")),value(p,"remarks"),user,value(p,"paymentMethodId"),csv(p,"labelIds"));}
    private void insertTemplate(String g,String user,LocalDate d,Map<String,Object>x){jdbc.update("INSERT INTO shopping(group_id,shopping_date,shopping_user_id,category_id,type,payment,settlement,amount,shopping_label_id,remarks,create_user_id,fixed_flag,create_date,update_date,payment_method_id,shopping_label_ids) VALUES (?,?,?,?,?,?,?,?,?,?,?,0,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP,?,?)",g,Timestamp.valueOf(d.atStartOfDay()),first(x.get("member_ids"),user),first(x.get("category_ids"),null),type(x.get("transaction_type")),0,settlement(x.get("settlement_status")),number(x.get("amount")),null,text(x.get("note")),user,first(x.get("payment_method_ids"),null),text(x.get("label_ids")));}
    private void masters(String g,Model m){m.addAttribute("categories",jdbc.queryForList("SELECT id,category_name name FROM category WHERE group_id=? AND disabled_flag=0 ORDER BY category_no",g));m.addAttribute("payments",jdbc.queryForList("SELECT id,payment_name name FROM payment_method WHERE group_id=? AND disabled_flag=0 ORDER BY payment_no",g));m.addAttribute("labels",jdbc.queryForList("SELECT id,label_name name FROM shopping_label WHERE group_id=? AND disabled_flag=0 ORDER BY label_no",g));m.addAttribute("members",jdbc.queryForList("SELECT u.user_id id,u.user_name name FROM group_member gm JOIN \"user\" u ON u.user_id=gm.user_id WHERE gm.group_id=? AND gm.approve_flag=1 AND u.delete_flag=0 ORDER BY gm.member_no,u.user_name,u.user_id",g));}
    private List<Map<String,Object>>patterns(String g,String t){return jdbc.queryForList("SELECT * FROM purchase_pattern WHERE group_id=? AND pattern_type=? AND disabled_flag=0 ORDER BY display_no",g,t);}
    private List<Map<String,Object>>search(String g,MultiValueMap<String,String>p){StringBuilder q=new StringBuilder("SELECT s.*,c.category_name,pm.payment_name,u.user_name FROM shopping s LEFT JOIN category c ON c.id=s.category_id LEFT JOIN payment_method pm ON pm.id=s.payment_method_id LEFT JOIN \"user\" u ON u.user_id=s.shopping_user_id WHERE s.group_id=?");List<Object>a=new ArrayList<>();a.add(g);cond(q,a,p,"dateFrom"," AND s.shopping_date>=?",true);cond(q,a,p,"dateTo"," AND s.shopping_date<?",true);String amountFrom=value(p,"amountFrom"),amountTo=value(p,"amountTo");if(!amountFrom.isBlank()){q.append(" AND s.amount>=?");a.add(Long.parseLong(amountFrom));}if(!amountTo.isBlank()){q.append(" AND s.amount<=?");a.add(Long.parseLong(amountTo));}in(q,a,p,"categoryIds","s.category_id");String t=value(p,"type");if(!t.isBlank()){q.append(" AND s.type=?");a.add(type(t));}in(q,a,p,"paymentIds","s.payment_method_id");in(q,a,p,"memberIds","s.shopping_user_id");String set=value(p,"settlement");if(!set.isBlank()){q.append(" AND s.settlement=?");a.add(settlement(set));}List<String> labels=p.get("labelIds");if(labels!=null&&!labels.isEmpty()){q.append(" AND (");for(int i=0;i<labels.size();i++){if(i>0)q.append(" OR ");q.append("?=ANY(string_to_array(COALESCE(s.shopping_label_ids,''),','))");a.add(labels.get(i));}q.append(')');}String note=value(p,"remarks");if(!note.isBlank()){q.append(" AND lower(COALESCE(s.remarks,'')) LIKE lower(?)");a.add("%"+note+"%");}q.append(" ORDER BY s.shopping_date DESC,s.id DESC");return jdbc.queryForList(q.toString(),a.toArray());}
    private Map<String,Object> purchaseSummary(List<Map<String,Object>> rows){Map<String,long[]> grouped=new TreeMap<>();long total=0;for(Map<String,Object> row:rows){long amount=row.get("amount") instanceof Number n?n.longValue():0;int type=row.get("type") instanceof Number n?n.intValue():1;long signed=type==2?-amount:amount;String payment=Optional.ofNullable(row.get("payment_name")).map(String::valueOf).filter(v->!v.isBlank()).orElse("未設定");long[] values=grouped.computeIfAbsent(payment,k->new long[2]);values[0]++;values[1]+=signed;total+=signed;}List<Map<String,Object>> payments=new ArrayList<>();grouped.forEach((name,values)->{Map<String,Object> item=new LinkedHashMap<>();item.put("name",name);item.put("count",values[0]);item.put("total",values[1]);payments.add(item);});Map<String,Object> result=new LinkedHashMap<>();result.put("count",(long)rows.size());result.put("total",total);result.put("payments",payments);return result;}
    private void cond(StringBuilder q,List<Object>a,MultiValueMap<String,String>p,String k,String sql,boolean date){String v=value(p,k);if(!v.isBlank()){q.append(sql);LocalDate d=parseDate(v);a.add(Timestamp.valueOf((k.equals("dateTo")?d.plusDays(1):d).atStartOfDay()));}}
    private void in(StringBuilder q,List<Object>a,MultiValueMap<String,String>p,String k,String col){List<String>v=p.get(k);if(v==null||v.isEmpty())return;q.append(" AND ").append(col).append(" IN (").append(String.join(",",Collections.nCopies(v.size(),"?"))).append(')');a.addAll(v);}
    private List<Map<String,Object>>monthStatus(String g,int y){List<Map<String,Object>>r=new ArrayList<>();for(int m=1;m<=12;m++){Map<String,Object>x=new HashMap<>();x.put("month",m);x.put("closed",closed(g,y,m));r.add(x);}return r;}
    private List<Map<String,Object>>monthlyMembers(String g,int y,int m){return jdbc.queryForList("SELECT u.user_id,u.user_name,COUNT(s.id) FILTER(WHERE s.type=1) expense_count,COALESCE(SUM(s.amount) FILTER(WHERE s.type=1),0) expense_amount,COUNT(s.id) FILTER(WHERE s.type=2) income_count,COALESCE(SUM(s.amount) FILTER(WHERE s.type=2),0) income_amount,COUNT(s.id) FILTER(WHERE s.settlement<>2) unsettled_count,COALESCE(SUM(s.amount) FILTER(WHERE s.settlement<>2),0) unsettled_amount FROM group_member gm JOIN \"user\" u ON u.user_id=gm.user_id LEFT JOIN shopping s ON s.shopping_user_id=u.user_id AND s.group_id=gm.group_id AND EXTRACT(YEAR FROM s.shopping_date)=? AND EXTRACT(MONTH FROM s.shopping_date)=? WHERE gm.group_id=? AND gm.approve_flag=1 GROUP BY u.user_id,u.user_name,gm.member_no ORDER BY gm.member_no,u.user_name,u.user_id",y,m,g);}
    private String invalidReferenceCase(String a){return "CASE WHEN NOT EXISTS(SELECT 1 FROM group_member gm WHERE gm.group_id="+a+".group_id AND gm.user_id="+a+".shopping_user_id AND gm.approve_flag=1) OR NOT EXISTS(SELECT 1 FROM category c WHERE c.group_id="+a+".group_id AND c.id="+a+".category_id AND c.disabled_flag=0) OR NOT EXISTS(SELECT 1 FROM payment_method pm WHERE pm.group_id="+a+".group_id AND pm.id="+a+".payment_method_id AND pm.disabled_flag=0) OR EXISTS(SELECT 1 FROM unnest(string_to_array(COALESCE("+a+".shopping_label_ids,''),',')) label_id WHERE label_id<>'' AND NOT EXISTS(SELECT 1 FROM shopping_label sl WHERE sl.group_id="+a+".group_id AND sl.id=label_id AND sl.disabled_flag=0)) THEN 1 ELSE 0 END";}
    private boolean invalidShopping(String g,long id){Integer n=jdbc.queryForObject("SELECT "+invalidReferenceCase("s")+" FROM shopping s WHERE s.group_id=? AND s.id=?",Integer.class,g,id);return n!=null&&n==1;}
    private int invalidReferences(String g,int y,int m){Integer shopping=jdbc.queryForObject("SELECT count(*) FROM shopping s WHERE s.group_id=? AND EXTRACT(YEAR FROM s.shopping_date)=? AND EXTRACT(MONTH FROM s.shopping_date)=? AND "+invalidReferenceCase("s")+"=1",Integer.class,g,y,m);Integer budgets=jdbc.queryForObject("SELECT count(*) FROM budgets b LEFT JOIN category c ON c.id=b.category_id AND c.group_id=b.group_id WHERE b.group_id=? AND b.year=? AND b.month=? AND (c.id IS NULL OR c.disabled_flag<>0)",Integer.class,g,y,m);return (shopping==null?0:shopping)+(budgets==null?0:budgets);}
    private int numberValue(Object value){return value instanceof Number n?n.intValue():0;}
    private boolean budgetReady(String g,int y,int m){Integer active=jdbc.queryForObject("SELECT count(*) FROM category WHERE group_id=? AND disabled_flag=0",Integer.class,g),budget=jdbc.queryForObject("SELECT count(*) FROM budgets b JOIN category c ON c.id=b.category_id WHERE b.group_id=? AND b.year=? AND b.month=? AND c.disabled_flag=0",Integer.class,g,y,m);return active!=null&&active>0&&Objects.equals(active,budget);}
    private int count(String g,String sql,int y,int m){Integer n=jdbc.queryForObject(sql,Integer.class,g,y,m);return n==null?0:n;}private boolean closed(String g,int y,int m){Integer n=jdbc.queryForObject("SELECT count(*) FROM fixed WHERE group_id=? AND year=? AND month=?",Integer.class,g,y,m);return n!=null&&n>0;}private boolean isClosed(String g,LocalDate d){return closed(g,d.getYear(),d.getMonthValue());}private boolean closedRow(String g,long id){Integer n=jdbc.queryForObject("SELECT count(*) FROM shopping s WHERE s.id=? AND s.group_id=? AND (s.fixed_flag=1 OR EXISTS(SELECT 1 FROM fixed f WHERE f.group_id=s.group_id AND f.year=EXTRACT(YEAR FROM s.shopping_date)::int AND f.month=EXTRACT(MONTH FROM s.shopping_date)::int))",Integer.class,id,g);return n!=null&&n>0;}
    private String group(HttpSession s){Object g=s.getAttribute("activeGroupId");if(g==null)throw new IllegalStateException("所属グループを選択してください");return g.toString();}private String value(MultiValueMap<String,String>p,String k){return Optional.ofNullable(p.getFirst(k)).orElse("").strip();}private String csv(MultiValueMap<String,String>p,String k){List<String>v=p.get(k);return v==null?"":String.join(",",v.stream().filter(x->x!=null&&!x.isBlank()).distinct().toList());}private LocalDate date(MultiValueMap<String,String>p,String k){return parseDate(value(p,k));}private LocalDate parseDate(String s){try{return LocalDate.parse(s);}catch(Exception e){throw new IllegalArgumentException("日付が不正です");}}private int positive(String s){try{return Math.max(1,Integer.parseInt(s));}catch(Exception e){throw new IllegalArgumentException("金額が不正です");}}private int type(Object s){return "INCOME".equals(String.valueOf(s))||"2".equals(String.valueOf(s))?2:1;}private int settlement(Object s){return "SETTLED".equals(String.valueOf(s))||"2".equals(String.valueOf(s))?2:1;}private int number(Object o){return o instanceof Number n?Math.max(1,n.intValue()):positive(String.valueOf(o));}private String first(Object o,String fallback){String s=text(o);return s.isBlank()?fallback:s.split(",")[0];}private String text(Object o){return o==null?"":String.valueOf(o);}
}
